<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue';
import type {ArchiveFilters,ArchiveOrder} from '@quote/contracts';
import {ArchiveController,archiveFilterForm,isFiltersDirty,restoreAppliedFilters,archivePanels,archiveTabs,archiveGroups,beijingTime,canProcessOrder,confirmationAmount,createArchiveState,orderStatus,orderStatuses,paymentFilters,receivableLabel,type ArchiveTab} from '@quote/archive-client';
import {downloadFile,request} from '../api';
import SourceFiles from './SourceFiles.vue';
const sourceActivity=reactive<Record<string,boolean>>({});
const props=defineProps<{locked:boolean}>();
const emit=defineEmits<{(e:'busy-changed',value:boolean):void;(e:'failure',value:unknown):void;(e:'process-order',value:ArchiveOrder):void}>();
const state=reactive(createArchiveState()),tab=ref<ArchiveTab>('source'),working=ref(false),fileError=ref('');
const controller=new ArchiveController(request,state,e=>emit('failure',e));
const emptyFilters=()=>archiveFilterForm();
const filters=reactive(emptyFilters());
const filtersDirty=computed(()=>isFiltersDirty(filters,state.applied));
const ownBusy=computed(()=>working.value||state.listLoading||state.detailLoading||state.hospitalsLoading||Object.values(sourceActivity).some(Boolean)),locked=computed(()=>props.locked||ownBusy.value);
watch(ownBusy,value=>emit('busy-changed',value),{flush:'sync',immediate:true});
const pages=computed(()=>state.page?Math.max(1,Math.ceil(state.page.total/state.page.pageSize)):1);
const refsOpen=reactive<Record<string,boolean>>({});
const activeGroup=computed(()=>archiveGroups.find(g=>g.sections.includes(tab.value))!);
const panels=computed(()=>state.detail?archivePanels(state.detail)[tab.value]:[]);
const files=computed(()=>state.detail?.quotes.flatMap(q=>q.files.map(f=>({...f,version:q.quoteNo+' · R'+q.revisionNo+' / V'+q.versionNo})))||[]);
const hospitalOptions=computed(()=>[{id:'',name:'全部可查看医院'},...state.hospitals]);
const statuses=[['','全部状态'],...orderStatuses],owners=[['','全部可查看'],['mine','我负责的订单'],['readonly','其他负责人（只读）']];
const picked=(event:unknown)=>Number((event as {detail:{value:string}}).detail.value);
const date=(event:unknown)=>(event as {detail:{value:string}}).detail.value;
function hospitalName(){return hospitalOptions.value.find(h=>h.id===filters.hospitalId)?.name||'全部可查看医院';}
function label(options:readonly(readonly string[])[],value:string){return options.find(s=>s[0]===value)?.[1]||options[0]?.[1];}
async function submit(){if(locked.value)return;fileError.value='';await controller.query({...filters} as ArchiveFilters);}
async function reset(){if(locked.value)return;Object.assign(filters,emptyFilters());await submit();}
async function open(id:string){if(locked.value)return;tab.value='source';fileError.value='';await controller.open(id);}
async function back(){if(locked.value)return;fileError.value='';restoreAppliedFilters(filters,state.applied);await controller.back();}
async function move(page:number){if(locked.value)return;restoreAppliedFilters(filters,state.applied);await controller.move(page);}
async function refresh(){if(locked.value)return;fileError.value='';if(state.mode==='detail')await controller.open(state.selectedId);else{restoreAppliedFilters(filters,state.applied);await Promise.all([controller.hospitals(),controller.back()]);}}
async function download(file:{id:string;format:'pdf'|'xlsx';filename:string}){if(locked.value)return;working.value=true;fileError.value='';try{await downloadFile(file.id,file.format,file.filename);}catch(e){fileError.value=e instanceof Error?e.message:'下载失败，请重试';emit('failure',e);}finally{working.value=false;}}
function processOrder(){if(locked.value||!state.detail||!canProcessOrder(state.detail.order))return;emit('process-order',state.detail.order);}
let ready:Promise<unknown>=Promise.resolve();onMounted(()=>{ready=Promise.all([controller.hospitals(),controller.query({...filters} as ArchiveFilters)]);});
onBeforeUnmount(()=>{controller.dispose();emit('busy-changed',false);});
defineExpose({refresh,openOrder:async(id:string)=>{await ready;await open(id);}});
</script>
<template>
 <view class="archive">
  <template v-if="state.mode==='list'">
   <text class="eyebrow">按采购单归档</text><text class="title">历史订单</text><text class="subtle">本人订单与当前负责医院历史；档案页面只读。</text>
   <view class="filters">
    <label class="field wide"><text>医院</text><picker :disabled="locked" :range="hospitalOptions" range-key="name" :value="Math.max(0,hospitalOptions.findIndex(h=>h.id===filters.hospitalId))" @change="filters.hospitalId=hospitalOptions[picked($event)]!.id"><view class="select">{{hospitalName()}} ⌄</view></picker></label>
    <label class="field"><text>实际接收日期（起）</text><picker mode="date" :disabled="locked" :value="filters.receivedFrom" @change="filters.receivedFrom=date($event)"><view class="select">{{filters.receivedFrom||'不限'}} ⌄</view></picker></label><label class="field"><text>实际接收日期（止）</text><picker mode="date" :disabled="locked" :value="filters.receivedTo" @change="filters.receivedTo=date($event)"><view class="select">{{filters.receivedTo||'不限'}} ⌄</view></picker></label>
    <label class="field wide"><text>单号、报价号、药品或规格</text><input v-model="filters.keyword" maxlength="100" :disabled="locked" placeholder="包含所有采购修订" @confirm="submit" /></label>
    <label class="field"><text>业务状态</text><picker :range="statuses.map(s=>s[1])" :value="Math.max(0,statuses.findIndex(s=>s[0]===filters.status))" :disabled="locked" @change="filters.status=statuses[picked($event)]![0]"><view class="select">{{label(statuses,filters.status)}} ⌄</view></picker></label>
    <label class="field"><text>查看范围</text><picker :range="owners.map(s=>s[1])" :value="Math.max(0,owners.findIndex(s=>s[0]===filters.ownership))" :disabled="locked" @change="filters.ownership=owners[picked($event)]![0]"><view class="select">{{label(owners,filters.ownership)}} ⌄</view></picker></label>
    <label class="field wide"><text>回款情况</text><picker :range="paymentFilters.map(s=>s[1])" :value="Math.max(0,paymentFilters.findIndex(s=>s[0]===filters.payment))" :disabled="locked" @change="filters.payment=paymentFilters[picked($event)]![0]"><view class="select">{{label(paymentFilters,filters.payment)}} ⌄</view></picker></label>
   </view><view class="actions"><button class="primary" :disabled="locked" @click="submit">{{state.listLoading?'正在查询…':'查询'}}</button><button :disabled="locked" @click="reset">清空筛选</button></view>
   <view v-if="filtersDirty" class="filter-note">筛选已修改，点击查询后生效；当前结果仍按已查询条件显示。</view>
   <view v-if="state.hospitalsError" class="error">医院筛选读取失败：{{state.hospitalsError}}<button class="text-button" :disabled="locked" @click="controller.hospitals()">重试</button></view>
   <view v-if="state.listError" class="error">查询失败：{{state.listError}}<button class="text-button" :disabled="locked" @click="back">重新查询</button></view><text v-if="state.listLoading" class="empty">正在读取订单档案…</text>
   <template v-if="state.page&&!state.listLoading"><view class="results"><text>共 {{state.page.total}} 张采购单</text><text class="tiny">实际接收日期、单号倒序</text></view>
    <button v-for="item in state.page.items" :key="item.id" class="order-row" :disabled="locked" @click="open(item.id)"><view class="row-heading"><text class="hospital">{{item.hospitalName}}</text><text class="tag">{{orderStatus(item.status)}} ›</text></view><text class="subtle small">{{item.orderNo}} · R{{item.revisionNo}} · {{item.receivedDate}}</text><text v-if="item.matchedRevisions.length" class="subtle small">命中采购修订 {{item.matchedRevisions.map(n=>'R'+n).join('、')}}</text><view class="row-facts"><view><text class="tiny">最终确认金额</text><text>{{confirmationAmount(item)}}</text></view><view><text class="tiny">系统未收余额（元）</text><text>{{item.receivable?.balance||'—'}}</text></view></view><text class="small subtle">{{receivableLabel(item)}}{{item.receivable?' · 到期 '+item.receivable.dueDate:''}}</text><text class="small subtle">当前负责人 {{item.owner.name}} · 原负责人 {{item.originalOwner.name}}</text><text class="access">{{canProcessOrder(item)?'本人可处理订单 · 档案只读':'只读查阅'}}</text></button>
    <text v-if="!state.page.items.length" class="empty">没有符合当前筛选的订单。</text><view class="pagination"><button :disabled="locked||state.page.page<=1" @click="move(state.page!.page-1)">上一页</button><text>第 {{state.page.page}} / {{pages}} 页</text><button :disabled="locked||state.page.page>=pages" @click="move(state.page!.page+1)">下一页</button></view><text class="tiny subtle">读取于 {{beijingTime(state.page.asOf)}}</text>
   </template><text class="footnote">档案包含未完成及已作废记录，不作为需求统计；不限最近三次报价。</text>
  </template>
  <template v-else>
   <button class="text-button" :disabled="locked" @click="back">← 返回原筛选列表</button><text v-if="state.detailLoading" class="empty">正在读取档案详情…</text><view v-if="state.detailError" class="error">详情读取失败：{{state.detailError}}<button class="text-button" :disabled="locked" @click="controller.open(state.selectedId)">重新读取</button></view>
   <template v-if="state.detail"><text class="eyebrow">{{state.detail.order.hospitalName}}</text><text class="title detail-title">{{state.detail.order.orderNo}}</text><text class="subtle small">{{orderStatus(state.detail.order.status)}} · {{state.detail.order.receivedDate||'待核实'}} · {{state.detail.order.source==='historical_backfill'?'历史补录':state.detail.order.source==='hospital_self'?'医院录入':'销售代录'}}</text><view class="facts"><text>当前订单负责人：{{state.detail.order.owner.name}}</text><text>原订单负责人：{{state.detail.order.originalOwner.name}}</text><text>最终确认金额：{{confirmationAmount(state.detail.order)}}</text><text>应收情况：{{receivableLabel(state.detail.order)}}</text></view>
    <button v-if="canProcessOrder(state.detail.order)" class="primary full" :disabled="locked" @click="processOrder">进入当前业务处理</button><text v-else class="access">当前订单只读；已完成和已作废订单仅供查阅。</text>
    <scroll-view scroll-x class="tab-scroll"><view class="tabs"><button v-for="group in archiveGroups" :key="group.label" :class="{selected:activeGroup===group}" :disabled="locked" @click="tab=group.sections[0]">{{group.label}}</button></view></scroll-view><scroll-view v-if="activeGroup.sections.length>1" scroll-x class="section-scroll"><view class="section-tabs"><button v-for="section in activeGroup.sections" :key="section" :class="{selected:tab===section}" :disabled="locked" @click="tab=section">{{archiveTabs.find(t=>t[0]===section)?.[1]}}</button></view></scroll-view>
    <view v-for="(panel,index) in panels" :key="tab+'-'+index" class="panel"><text class="panel-title">{{panel.title}}</text><text v-if="panel.note" class="subtle small panel-note">{{panel.note}}</text><view v-if="panel.facts" class="panel-facts"><view v-for="fact in panel.facts" :key="fact[0]"><text class="tiny subtle">{{fact[0]}}</text><text class="fact-value">{{fact[1]}}</text></view></view><scroll-view v-if="panel.columns&&panel.rows?.length" scroll-x class="table-scroll"><view class="table" :style="{width:Math.max(480,panel.columns.length*126)+'px'}"><view class="table-row table-head"><text v-for="column in panel.columns" :key="column" class="cell">{{column}}</text></view><view v-for="(row,i) in panel.rows" :key="i" class="table-row"><text v-for="(cell,j) in row" :key="j" class="cell">{{cell}}</text></view></view></scroll-view><view v-if="panel.references?.length"><button class="text-button refs-toggle" :disabled="locked" @click="refsOpen[tab+index]=!refsOpen[tab+index]">{{refsOpen[tab+index]?'收起引用信息':'查看引用信息'}}</button><view v-if="refsOpen[tab+index]" class="panel-facts references"><view v-for="(reference,j) in panel.references" :key="j"><text class="tiny subtle">{{reference[0]}}</text><text class="fact-value">{{reference[1]}}</text></view></view></view></view>
    <view v-if="tab==='source'" class="panel"><text class="panel-title">原始采购资料</text><SourceFiles v-if="state.detail.historical" :reference="{kind:'historical_order',orderId:state.detail.order.id}" readonly :locked="props.locked||working" @busy-changed="sourceActivity['history']=$event" @failure="emit('failure',$event)"/><template v-else><view v-for="revision in state.detail.revisions" :key="revision.id"><text>R{{revision.revisionNo}} 原单</text><SourceFiles :reference="{kind:'purchase_revision',orderId:state.detail.order.id,revisionId:revision.id}" readonly :locked="props.locked||working" @busy-changed="sourceActivity[revision.id]=$event" @failure="emit('failure',$event)"/></view></template></view>
    <view v-if="tab==='files'&&files.length" class="panel"><text class="panel-title">下载已生成文件</text><view v-for="file in files" :key="file.id" class="file-row"><text>{{file.filename}}</text><text class="tiny subtle">{{file.version}} · {{beijingTime(file.createdAt)}}</text><button :disabled="locked" @click="download(file)">{{working?'正在准备…':'下载 '+file.format.toUpperCase()}}</button></view></view>
   </template>
  </template><view v-if="fileError" class="error">{{fileError}}</view>
 </view>
</template>
<style scoped>
.archive{width:100%;min-width:0;padding:18px 0 30px;color:#24382f;overflow:hidden}.eyebrow{display:block;font-size:11px;color:#7a897e;margin:4px 0 8px}.title{display:block;font-size:25px;font-weight:600;margin-bottom:12px;line-height:1.35}.detail-title{font-size:21px;overflow-wrap:anywhere;margin-top:5px}.subtle{display:block;color:#77877c;font-size:12px;line-height:1.65}.small{font-size:11px}.tiny{display:block;font-size:10px;line-height:1.6;color:#7b8d80}.filters{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px 12px;padding:24px 0 18px}.field{display:block;min-width:0}.wide{grid-column:1/-1}.field>text{display:block;font-size:11px;color:#53685c;margin-bottom:6px}.field input,.select{height:43px;padding:9px 10px;background:#fff;border:1px solid #cfdbd2;border-radius:4px;font-size:13px;line-height:24px;box-sizing:border-box;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.field input{width:100%}button{font-size:12px;background:#fff;color:#215f46;border:1px solid #cfdbd2;border-radius:4px;line-height:24px;padding:8px 11px;min-height:42px;margin:0;transition:background .15s}button:after{border:0}button[disabled]{opacity:.45}.primary{background:#215f46;color:#fff;border-color:#215f46}.full{width:100%}.actions{display:flex;gap:12px;padding-bottom:23px;border-bottom:1px solid #dfe7e1}.actions button{flex:1}.results{display:flex;justify-content:space-between;align-items:center;padding:23px 0 5px;font-size:12px}.order-row{display:block;text-align:left;width:100%;padding:19px 0;border:0;border-bottom:1px solid #dfe7e1;border-radius:0;font-size:12px;white-space:normal}.row-heading{display:flex;justify-content:space-between;gap:12px;margin-bottom:6px}.hospital{font-size:16px;font-weight:550}.tag{font-size:10px;color:#6f8275;flex-shrink:0}.row-facts{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;padding:13px 0 10px;line-height:1.6}.row-facts>view>text{display:block}.access{display:block;font-size:10px;color:#215f46;margin-top:7px;line-height:1.7}.pagination{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:22px 0 12px;font-size:11px;color:#74877a}.pagination button{padding:7px 10px;min-height:38px}.empty{display:block;padding:40px 0;font-size:12px;color:#7a8a7e}.footnote{display:block;font-size:10px;color:#859488;line-height:1.7;margin-top:20px}.error{padding:12px;color:#9b3e32;background:#fbf2ef;font-size:12px;line-height:1.7;white-space:pre-wrap;margin:14px 0}.text-button{border:0;padding:8px 0;min-height:36px;display:inline-block;background:transparent;font-size:11px}.facts{display:grid;gap:7px;padding:17px 0 20px;font-size:12px;line-height:1.6}.tab-scroll{width:100%;max-width:100%;margin:20px 0 0;border-bottom:1px solid #dfe7e1}.tabs{display:flex;width:max-content;min-width:100%;gap:20px;white-space:nowrap}.tabs button{flex-shrink:0;white-space:nowrap;padding:13px 0;border:0;border-bottom:2px solid transparent;border-radius:0;font-size:12px;color:#7b8a7f}.tabs .selected{border-bottom-color:#215f46;color:#215f46}.panel{padding:23px 0;border-bottom:1px solid #dfe7e1;min-width:0}.panel-title{display:block;font-size:14px;font-weight:550;white-space:pre-line;line-height:1.7;overflow-wrap:anywhere}.panel-note{margin:10px 0}.panel-facts{display:grid;gap:10px;margin:15px 0;font-size:12px;min-width:0}.panel-facts>view{display:grid;grid-template-columns:110px minmax(0,1fr);gap:10px}.fact-value{white-space:pre-line;overflow-wrap:anywhere;line-height:1.65;font-size:11px}.table-scroll{width:100%;max-width:100%;margin-top:15px;overflow:hidden}.table{font-size:11px}.table-row{display:flex;border-bottom:1px solid #dfe7e1;align-items:stretch}.table-head{background:#f2f6f2;color:#7b8b7f;font-size:10px}.cell{flex:1;min-width:0;padding:12px 9px;box-sizing:border-box;line-height:1.7;white-space:pre-line;overflow-wrap:anywhere}.file-row{padding:18px 0;border-bottom:1px solid #dfe7e1;font-size:12px;overflow-wrap:anywhere}.file-row>text{display:block}.file-row button{margin-top:10px} @media(prefers-reduced-motion:reduce){*{transition:none!important}}
.section-scroll{width:100%;max-width:100%;overflow:hidden;margin-top:8px}.section-tabs{display:flex;gap:18px;width:max-content}.section-tabs button{border:0;background:transparent;font-size:11px;padding:7px 0;color:#7b8a7f;white-space:nowrap;flex-shrink:0}.section-tabs .selected{color:#215f46;text-decoration:underline}.refs-toggle{font-size:10px;color:#7d8c80}.references .fact-value{font-size:9px}.filter-note{font-size:11px;line-height:1.7;color:#215f46;background:#eef5f0;padding:10px 12px;margin:14px 0;border-left:2px solid #215f46}</style>
